var i=`ai-generated-code-governance`;var n=120;var a={en:[{id:`T120-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`AI-Generated Code Governance`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Agentic workflows let AI systems plan, call tools, modify artifacts and iterate toward a goal.`},{id:`B`,text:`AI-generated code governance establishes policies for provenance, accountability, quality, security and licensing across AI-assisted delivery.`},{id:`C`,text:`Context engineering curates the information, tools and constraints available to an AI model for a task.`},{id:`D`,text:`AI can accelerate test-case discovery, fixture creation and failure analysis, but generated tests still need an independent behavioral oracle.`}]},{id:`T120-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`AI-Generated Code Governance`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Define permitted tools and data, code review ownership, test gates, third-party license checks, artifact provenance, logging and handling of sensitive source.`},{id:`B`,text:`Supply only relevant files, current API contracts, examples, acceptance criteria and forbidden changes.`},{id:`C`,text:`Review against the specification, trace data and authorization paths, inspect all changed files and dependencies, and execute tests independently.`},{id:`D`,text:`Treat external text as data, enforce instruction hierarchy in the agent runtime, sandbox tools, restrict file/network permissions and protect secrets.`}]},{id:`T120-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`A team requires AI-created changes to pass standard PR review, CI, dependency audits and architecture rules.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`For an AI-generated booking endpoint, verify tenant scoping in every query, atomic availability updates and error behavior under concurrent requests; the endpoint 'working' manually is insufficient.`},{id:`B`,text:`A team benchmarks agents on ten real Nx/Angular/Node.js maintenance tasks, scoring test pass rate, forbidden-file changes and engineer review time, not just output length.`},{id:`C`,text:`Instead of 'build an admin page,' specify route, permissions, data fields, loading states, error UX, component conventions, tests and files the agent may modify.`},{id:`D`,text:`Sensitive migrations need a named human approver and an independently tested recovery plan.`}]},{id:`T120-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`AI-Generated Code Governance`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Overly bureaucratic governance drives shadow AI usage; overly permissive rules create silent risk.`},{id:`B`,text:`Benchmark contamination, flaky tests and cherry-picked tasks mislead results.`},{id:`C`,text:`Unbounded autonomy can produce unrelated edits, fabricated tests or leaked secrets.`},{id:`D`,text:`Overly prescriptive specs constrain harmless design choices; vague ones create plausible but wrong code.`}]},{id:`T120-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`The human team remains responsible for shipped behavior regardless of who drafted code.`}]}]},{id:`T120-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`Code generated by AI no longer needs human ownership, licensing checks or review.`}]}]},{id:`T120-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Maintain clear exceptions, developer training and periodic review as tools evolve.`}]}]},{id:`T120-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`AI-Generated Code Governance`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`License and provenance checks can be skipped for AI-assisted pull requests.`},{id:`B`,text:`Define permitted tools and data, code review ownership, test gates, third-party license checks, artifact provenance, logging and handling of sensitive source.`},{id:`C`,text:`AI-generated code governance establishes policies for provenance, accountability, quality, security and licensing across AI-assisted delivery.`},{id:`D`,text:`An autonomous coding agent should receive unrestricted production credentials by default.`}]},{id:`T120-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`AI-Generated Code Governance`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Sandboxing cannot reduce the impact of a malicious instruction in tool output.`},{id:`B`,text:`Sensitive migrations need a named human approver and an independently tested recovery plan.`},{id:`C`,text:`Code generated by AI no longer needs human ownership, licensing checks or review.`},{id:`D`,text:`Maintain clear exceptions, developer training and periodic review as tools evolve.`}]},{id:`T120-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A team requires AI-created changes to pass standard PR review, CI, dependency audits and architecture rules.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Give an agent a cancellation feature brief and ask it first to extract invariants, ambiguities and acceptance tests. Only then permit implementation within declared module boundaries.`},{id:`B`,text:`Ask an agent to draft a one-page AI coding policy with approved data, tool access, review rules, security controls, audit evidence, exception handling and accountable owners.`},{id:`C`,text:`Ask an agent to plan a two-module feature as scoped tasks, specifying tool permissions, checkpoints, approval gates and evidence required at handoff.`},{id:`D`,text:`Ask an agent to design an internal benchmark harness with fixed tasks, independent acceptance tests, safety checks, cost tracking and versioned result reports.`}]},{id:`T120-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Who signs off on correctness and security when a pull request is mostly AI-generated?`}]}]},{id:`T120-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A team requires AI-created changes to pass standard PR review, CI, dependency audits and architecture rules.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`AI-Generated Code Governance`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T120-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A team requires AI-created changes to pass standard PR review, CI, dependency audits and architecture rules.`,b:!0},{t:` — propose three checks for `},{t:`AI-Generated Code Governance`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T120-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A team requires AI-created changes to pass standard PR review, CI, dependency audits and architecture rules.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T120-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`AI-Generated Code Governance`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A team requires AI-created changes to pass standard PR review, CI, dependency audits and architecture rules.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T120-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Управління кодом, згенерованим ШІ`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Агентні процеси дозволяють ШІ планувати, викликати інструменти, змінювати артефакти й повторювати кроки до мети.`},{id:`B`,text:`Управління AI-кодом встановлює правила походження, відповідальності, якості, безпеки та ліцензій у розробці з ШІ.`},{id:`C`,text:`Інженерія контексту керує інформацією, інструментами та обмеженнями, доступними ШІ для задачі.`},{id:`D`,text:`ШІ пришвидшує пошук тестових випадків, створення фікстур та аналіз падінь, але згенерованим тестам усе одно потрібен незалежний еталон поведінки.`}]},{id:`T120-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Управління кодом, згенерованим ШІ`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Визначте дозволені інструменти й дані, відповідальних за review, тестові gates, перевірки ліцензій, походження артефактів, журнали й роботу з чутливим кодом.`},{id:`B`,text:`Надавайте релевантні файли, чинні API-контракти, приклади, критерії приймання й заборонені зміни.`},{id:`C`,text:`Перевіряйте за специфікацією, трасуйте дані та права доступу, переглядайте всі змінені файли й залежності та незалежно запускайте тести.`},{id:`D`,text:`Сприймайте зовнішній текст як дані, забезпечуйте ієрархію інструкцій у runtime агента, ізолюйте інструменти, обмежуйте файли/мережу й захищайте секрети.`}]},{id:`T120-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Команда вимагає для AI-змін звичайний PR review, CI, аудит залежностей та архітектурні правила.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Для згенерованого booking endpoint перевірте tenant scoping у кожному запиті, атомарне оновлення доступності та помилки за конкурентних запитів; ручна демонстрація недостатня.`},{id:`B`,text:`Команда тестує агентів на десяти реальних задачах підтримки Nx/Angular/Node.js, вимірюючи проходження тестів, зміни заборонених файлів і час review, а не обсяг відповіді.`},{id:`C`,text:`Замість «зроби адмінку» задайте route, права, поля, loading-стани, UX помилок, конвенції компонентів, тести та дозволені файли.`},{id:`D`,text:`Чутливі міграції потребують конкретного відповідального й незалежно перевіреного відновлення.`}]},{id:`T120-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Управління кодом, згенерованим ШІ`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Надмірна бюрократія стимулює приховане використання ШІ, а надто вільні правила створюють непомітний ризик.`},{id:`B`,text:`Засмічені бенчмарки, нестабільні тести й вибір зручних задач спотворюють результати.`},{id:`C`,text:`Необмежена автономія створює сторонні зміни, вигадані результати тестів або витік секретів.`},{id:`D`,text:`Надто детальна специфікація диктує несуттєві рішення, а нечітка породжує правдоподібний, але неправильний код.`}]},{id:`T120-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`За випущену поведінку відповідає команда незалежно від автора чернетки.`}]}]},{id:`T120-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Код, згенерований ШІ, більше не потребує людської відповідальності, перевірки ліцензій чи рев’ю.`}]}]},{id:`T120-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Потрібні зрозумілі винятки, навчання й регулярний перегляд політик.`}]}]},{id:`T120-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Управління кодом, згенерованим ШІ`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Перевірки ліцензій і походження можна пропускати для PR за участю ШІ.`},{id:`B`,text:`Визначте дозволені інструменти й дані, відповідальних за review, тестові gates, перевірки ліцензій, походження артефактів, журнали й роботу з чутливим кодом.`},{id:`C`,text:`Управління AI-кодом встановлює правила походження, відповідальності, якості, безпеки та ліцензій у розробці з ШІ.`},{id:`D`,text:`Автономному кодинговому агенту слід за замовчуванням давати необмежені продакшн-доступи.`}]},{id:`T120-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Управління кодом, згенерованим ШІ`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Пісочниця не може зменшити шкоду від шкідливої інструкції у виводі інструмента.`},{id:`B`,text:`Чутливі міграції потребують конкретного відповідального й незалежно перевіреного відновлення.`},{id:`C`,text:`Код, згенерований ШІ, більше не потребує людської відповідальності, перевірки ліцензій чи рев’ю.`},{id:`D`,text:`Потрібні зрозумілі винятки, навчання й регулярний перегляд політик.`}]},{id:`T120-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Команда вимагає для AI-змін звичайний PR review, CI, аудит залежностей та архітектурні правила.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Дайте агенту опис скасування і попросіть спершу виписати інваріанти, неоднозначності й приймальні тести. Лише потім дозвольте реалізацію в заданих межах модулів.`},{id:`B`,text:`Попросіть агента скласти односторінкову політику AI-коду: дозволені дані, доступ до інструментів, review, безпека, аудит, винятки й відповідальні.`},{id:`C`,text:`Попросіть агента розбити фічу на задачі двох модулів із дозволеними інструментами, контрольними точками, затвердженням і доказами готовності.`},{id:`D`,text:`Попросіть агента описати внутрішній benchmark harness із фіксованими задачами, незалежними тестами, safety-перевірками, обліком вартості та версіонованими звітами.`}]},{id:`T120-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Хто відповідає за правильність і безпеку, якщо PR майже повністю згенерований ШІ?`}]}]},{id:`T120-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Команда вимагає для AI-змін звичайний PR review, CI, аудит залежностей та архітектурні правила.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Управління кодом, згенерованим ШІ`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T120-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Команда вимагає для AI-змін звичайний PR review, CI, аудит залежностей та архітектурні правила.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Управління кодом, згенерованим ШІ`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T120-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Команда вимагає для AI-змін звичайний PR review, CI, аудит залежностей та архітектурні правила.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T120-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Управління кодом, згенерованим ШІ`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Команда вимагає для AI-змін звичайний PR review, CI, аудит залежностей та архітектурні правила.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var r={slug:i,topicId:120,questions:a};export{r as default,a as questions,i as slug,n as topicId};